44:         BlobStore.StoredBlob stored = blobStore.put(fileId, content, maximumBytes);
45:         Instant now = Instant.now();
46:         FileAsset asset = new FileAsset(fileId, ownerId, safeName(originalName), safeMediaType(mediaType),
47:                 stored.sizeBytes(), stored.sha256(), LOCAL_BACKEND, null, stored.storageKey(), AVAILABLE,
48:                 now, now, null);
49:         try {
50:             repository.insert(asset);
51:             repository.bind(UUID.randomUUID().toString(), fileId, ownerId, domainType, domainId, role, now);
52:             return asset;
53:         } catch (RuntimeException exception) {
54:             try {
55:                 blobStore.delete(stored.storageKey());
56:             } catch (RuntimeException cleanupException) {
57:                 exception.addSuppressed(cleanupException);
58:             }
59:             throw exception;
60:         }
61:     }
