69:         Path file = storageProperties.transcriptFile(sessionId);
70:         if (!Files.isRegularFile(file) || Files.isSymbolicLink(file)) return List.of();
71:         try (var channel = java.nio.channels.FileChannel.open(file, StandardOpenOption.READ)) {
72:             long size = channel.size();
73:             long offset = Math.max(0, size - 2_097_152);
74:             var bytes = java.nio.ByteBuffer.allocate((int) (size - offset));
75:             channel.position(offset);
76:             while (bytes.hasRemaining() && channel.read(bytes) > 0) { /* 有界文件读取。 */ }
77:             String tail = new String(bytes.array(), 0, bytes.position(), StandardCharsets.UTF_8);
78:             if (offset > 0) {
79:                 int newline = tail.indexOf('\n');
80:                 tail = newline < 0 ? "" : tail.substring(newline + 1);
81:             }
82:             var records = new java.util.ArrayDeque<TranscriptMessageDto>();
83:             for (String line : tail.split("\\R")) {
84:                 if (line.isBlank()) continue;
85:                 try {
86:                     var value = objectMapper.readValue(line, TranscriptMessageDto.class);
87:                     records.addLast(new TranscriptMessageDto(value.id(), value.turnId(), value.role(),
88:                             value.content(), value.createdAt(), value.status(), null, List.of(), null, null, value.proactive()));
89:                     if (records.size() > Math.max(1, Math.min(24, limit))) records.removeFirst();
90:                 } catch (IOException exception) {
91:                     log.warn("跳过有界历史中的损坏记录：sessionId={}", sessionId);
92:                 }
93:             }
94:             return List.copyOf(records);
95:         } catch (IOException exception) {
96:             throw new IllegalArgumentException("读取近期聊天记录失败", exception);
97:         }
