148:         emitter.onCompletion(() -> {
149:             // 浏览器主动断开时，同时停止 SSE 消费线程与 Agent 生产线程。
150:             if (!terminalDelivered.get()) {
151:                 sender.interrupt();
152:                 session.closeTransport();
153:             }
154:         });
155: 
156:         return emitter;
157:     }
