16: public record AgentImageAttachment(String mediaType, byte[] data) {
17: 
18:     /** 单张图片上限；超过后拒绝而不是悄悄截断或压缩。 */
19:     public static final int MAX_BYTES = 10 * 1024 * 1024;
20: 
21:     /** 仅接受模型适配器普遍支持的四种位图格式。 */
22:     private static final Set<String> SUPPORTED = Set.of("image/png", "image/jpeg", "image/webp", "image/gif");
23: 
24:     public AgentImageAttachment {
25:         if (mediaType == null || !SUPPORTED.contains(mediaType.toLowerCase(java.util.Locale.ROOT))) {
26:             throw new IllegalArgumentException("不支持的图片格式，仅支持 PNG、JPEG、WebP 与 GIF");
27:         }
28:         mediaType = mediaType.toLowerCase(java.util.Locale.ROOT);
29:         if (data == null || data.length == 0) {
30:             throw new IllegalArgumentException("图片内容为空");
31:         }
32:         if (data.length > MAX_BYTES) {
33:             throw new IllegalArgumentException("图片超过 10 MiB 上限");
34:         }
35:         data = data.clone();
36:     }
37: 
38:     /** 防御性复制，避免调用方在模型调用期间改写字节。 */
39:     @Override
40:     public byte[] data() {
41:         return data.clone();
42:     }
43: 
44:     /** 只读大小摘要，校验预算不必复制整张图片。 */
45:     public int sizeBytes() { return data.length; }
46: 
47:     /** 供模型适配器使用的 Base64 内容，只在内存中生成。 */
48:     public String base64() {
49:         return Base64.getEncoder().encodeToString(data);
50:     }
51: 
52:     /** 禁止把图片字节写进日志或异常信息。 */
53:     @Override
54:     public String toString() {
55:         return "AgentImageAttachment[mediaType=" + mediaType + ", bytes=" + data.length + "]";
