package butvan.agent.network.material.repository;

import butvan.agent.network.material.model.ChatMaterial;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** 对话档案（素材）SQLite 持久化仓库。 */
@Repository
@RequiredArgsConstructor
public class ChatMaterialRepository {

    private final JdbcTemplate jdbcTemplate;

    public void insert(ChatMaterial material) {
        jdbcTemplate.update("""
                INSERT INTO chat_material (
                    id, owner_id, file_id, channel, session_kind, session_id, project_id,
                    session_title_snapshot, turn_id, category, sub_type, original_name,
                    media_type, size_bytes, sha256, archive_path, created_date, created_at, deleted_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                material.id(),
                material.ownerId(),
                material.fileId(),
                material.channel(),
                material.sessionKind(),
                material.sessionId(),
                material.projectId(),
                material.sessionTitleSnapshot(),
                material.turnId(),
                material.category(),
                material.subType(),
                material.originalName(),
                material.mediaType(),
                material.sizeBytes(),
                material.sha256(),
                material.archivePath(),
                material.createdDate(),
                material.createdAt().toString(),
                material.deletedAt() == null ? null : material.deletedAt().toString()
        );
    }

    public Optional<ChatMaterial> findByFileId(String ownerId, String fileId) {
        return jdbcTemplate.query("""
                SELECT * FROM chat_material
                WHERE owner_id = ? AND file_id = ? AND deleted_at IS NULL
                """, (rs, rowNum) -> map(rs), ownerId, fileId)
                .stream()
                .findFirst();
    }

    public PageResult search(String ownerId, Filter filter, int limit, int offset) {
        StringBuilder where = new StringBuilder(" WHERE owner_id = ? AND deleted_at IS NULL");
        List<Object> params = new ArrayList<>();
        params.add(ownerId);
        appendFilter(where, params, filter);

        Long totalObj = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM chat_material" + where,
                Long.class,
                params.toArray()
        );
        long total = totalObj == null ? 0L : totalObj;

        List<Object> queryParams = new ArrayList<>(params);
        queryParams.add(limit);
        queryParams.add(offset);
        List<ChatMaterial> items = jdbcTemplate.query(
                "SELECT * FROM chat_material" + where + " ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?",
                (rs, rowNum) -> map(rs),
                queryParams.toArray()
        );
        return new PageResult(items, total);
    }

    public SummaryResult summarize(String ownerId) {
        Map<String, Object> totals = jdbcTemplate.queryForMap("""
                SELECT COUNT(*) AS cnt, COALESCE(SUM(size_bytes), 0) AS bytes
                FROM chat_material
                WHERE owner_id = ? AND deleted_at IS NULL
                """, ownerId);
        long totalCount = ((Number) totals.get("cnt")).longValue();
        long totalBytes = ((Number) totals.get("bytes")).longValue();

        Map<String, Long> byCategory = groupCount(ownerId, "category");
        Map<String, Long> byChannel = groupCount(ownerId, "channel");
        Map<String, Long> bySessionKind = groupCount(ownerId, "session_kind");
        Map<String, Long> bySubType = groupCount(ownerId, "sub_type");

        List<SessionBucket> sessions = jdbcTemplate.query("""
                SELECT session_id,
                       MAX(session_title_snapshot) AS title,
                       MAX(channel) AS channel,
                       MAX(session_kind) AS session_kind,
                       COUNT(*) AS cnt,
                       MAX(created_at) AS latest_at
                FROM chat_material
                WHERE owner_id = ? AND deleted_at IS NULL
                GROUP BY session_id
                ORDER BY latest_at DESC
                LIMIT 100
                """, (rs, rowNum) -> new SessionBucket(
                rs.getString("session_id"),
                rs.getString("title"),
                rs.getString("channel"),
                rs.getString("session_kind"),
                rs.getLong("cnt"),
                Instant.parse(rs.getString("latest_at"))
        ), ownerId);

        return new SummaryResult(totalCount, totalBytes, byCategory, byChannel, bySessionKind, bySubType, sessions);
    }

    public int deleteByFileId(String ownerId, String fileId) {
        return jdbcTemplate.update(
                "DELETE FROM chat_material WHERE owner_id = ? AND file_id = ?",
                ownerId, fileId
        );
    }

    private Map<String, Long> groupCount(String ownerId, String column) {
        String sql = "SELECT " + column + " AS k, COUNT(*) AS cnt FROM chat_material "
                + "WHERE owner_id = ? AND deleted_at IS NULL GROUP BY " + column + " ORDER BY cnt DESC";
        Map<String, Long> result = new LinkedHashMap<>();
        jdbcTemplate.query(sql, rs -> {
            result.put(rs.getString("k"), rs.getLong("cnt"));
        }, ownerId);
        return result;
    }

    private void appendFilter(StringBuilder where, List<Object> params, Filter filter) {
        if (filter == null) return;
        if (hasText(filter.category())) {
            where.append(" AND category = ?");
            params.add(filter.category());
        }
        if (hasText(filter.subType())) {
            where.append(" AND sub_type = ?");
            params.add(filter.subType());
        }
        if (hasText(filter.channel())) {
            where.append(" AND channel = ?");
            params.add(filter.channel());
        }
        if (hasText(filter.sessionKind())) {
            where.append(" AND session_kind = ?");
            params.add(filter.sessionKind());
        }
        if (hasText(filter.sessionId())) {
            where.append(" AND session_id = ?");
            params.add(filter.sessionId());
        }
        if (hasText(filter.fromDate())) {
            where.append(" AND created_date >= ?");
            params.add(filter.fromDate());
        }
        if (hasText(filter.toDate())) {
            where.append(" AND created_date <= ?");
            params.add(filter.toDate());
        }
        if (hasText(filter.query())) {
            String like = "%" + filter.query().trim().toLowerCase() + "%";
            where.append(" AND (LOWER(original_name) LIKE ? OR LOWER(session_title_snapshot) LIKE ? "
                    + "OR LOWER(file_id) LIKE ? OR LOWER(archive_path) LIKE ?)");
            params.add(like);
            params.add(like);
            params.add(like);
            params.add(like);
        }
    }

    private boolean hasText(String value) {
        return value != null && !value.isBlank();
    }

    private ChatMaterial map(ResultSet rs) throws SQLException {
        String deletedAt = rs.getString("deleted_at");
        return new ChatMaterial(
                rs.getString("id"),
                rs.getString("owner_id"),
                rs.getString("file_id"),
                rs.getString("channel"),
                rs.getString("session_kind"),
                rs.getString("session_id"),
                rs.getString("project_id"),
                rs.getString("session_title_snapshot"),
                rs.getString("turn_id"),
                rs.getString("category"),
                rs.getString("sub_type"),
                rs.getString("original_name"),
                rs.getString("media_type"),
                rs.getLong("size_bytes"),
                rs.getString("sha256"),
                rs.getString("archive_path"),
                rs.getString("created_date"),
                Instant.parse(rs.getString("created_at")),
                deletedAt == null ? null : Instant.parse(deletedAt)
        );
    }

    public record Filter(
            String category,
            String subType,
            String channel,
            String sessionKind,
            String sessionId,
            String fromDate,
            String toDate,
            String query
    ) {
    }

    public record PageResult(List<ChatMaterial> items, long total) {
    }

    public record SessionBucket(
            String sessionId,
            String sessionTitle,
            String channel,
            String sessionKind,
            long count,
            Instant latestCreatedAt
    ) {
    }

    public record SummaryResult(
            long totalCount,
            long totalBytes,
            Map<String, Long> byCategory,
            Map<String, Long> byChannel,
            Map<String, Long> bySessionKind,
            Map<String, Long> bySubType,
            List<SessionBucket> sessions
    ) {
    }
}

package butvan.agent.network.material.service;

import butvan.agent.agents.agent.AgentImageAttachment;
import butvan.agent.agents.material.ChatMaterialRecorder;
import butvan.agent.network.file.model.FileAsset;
import butvan.agent.network.file.service.FileAssetService;
import butvan.agent.network.material.model.ChatMaterial;
import butvan.agent.network.material.repository.ChatMaterialRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.core.io.InputStreamResource;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.ByteArrayInputStream;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * 对话档案（素材）领域服务：负责将对话图片/文件按多级分类归档落盘，
 * 生成唯一文件 ID 并维护检索元数据。
 */
@Service
@RequiredArgsConstructor
public class ChatMaterialService implements ChatMaterialRecorder {

    private static final int MAX_PAGE_LIMIT = 100;

    private final FileAssetService fileAssetService;
    private final ChatMaterialRepository repository;

    @Override
    @Transactional
    public List<String> recordUserImages(SaveImagesCommand command) {
        if (command == null || command.images().isEmpty()) {
            return List.of();
        }
        String ownerId = requireIdentifier(command.ownerId(), "用户 ID");
        String sessionId = requireIdentifier(command.sessionId(), "会话 ID");
        String turnId = requireIdentifier(command.turnId(), "轮次 ID");
        String channel = normalizeEnum(command.channel(), "DESKTOP");
        String sessionKind = normalizeEnum(command.sessionKind(), "GENERAL");
        String sessionTitle = normalizeTitle(command.sessionTitle());
        String projectId = blankToNull(command.projectId());

        LocalDate today = LocalDate.now(ZoneId.systemDefault());
        String dateText = today.toString();
        String monthText = dateText.substring(0, 7);

        List<String> fileIds = new ArrayList<>(command.images().size());
        for (int index = 0; index < command.images().size(); index++) {
            AgentImageAttachment image = command.images().get(index);
            String subType = subTypeForMediaType(image.mediaType());
            String extension = extensionForSubType(subType);
            String relativeDirectory = String.join("/",
                    channel.toLowerCase(Locale.ROOT),
                    sessionKind.toLowerCase(Locale.ROOT),
                    sessionId,
                    "images",
                    subType,
                    monthText,
                    dateText
            );
            String originalName = "chat-image-" + dateText + "-" + (index + 1) + "." + extension;

            FileAsset asset = fileAssetService.createAndBindCategorized(
                    ownerId,
                    FileAssetService.DOMAIN_CHAT_MATERIAL,
                    turnId,
                    FileAssetService.ROLE_CHAT_ATTACHMENT,
                    relativeDirectory,
                    extension,
                    originalName,
                    image.mediaType(),
                    new ByteArrayInputStream(image.data()),
                    AgentImageAttachment.MAX_BYTES
            );

            String archivePath = relativeDirectory + "/" + asset.id() + "." + extension;
            Instant now = Instant.now();
            repository.insert(new ChatMaterial(
                    asset.id(),
                    ownerId,
                    asset.id(),
                    channel,
                    sessionKind,
                    sessionId,
                    projectId,
                    sessionTitle,
                    turnId,
                    "IMAGE",
                    subType.toUpperCase(Locale.ROOT),
                    asset.originalName(),
                    asset.mediaType(),
                    asset.sizeBytes(),
                    asset.sha256(),
                    archivePath,
                    dateText,
                    now,
                    null
            ));
            fileIds.add(asset.id());
        }
        return List.copyOf(fileIds);
    }

    public ChatMaterialRepository.PageResult list(
            String ownerId,
            String category,
            String subType,
            String channel,
            String sessionKind,
            String sessionId,
            String fromDate,
            String toDate,
            String query,
            int limit,
            int offset
    ) {
        int safeLimit = Math.max(1, Math.min(MAX_PAGE_LIMIT, limit));
        int safeOffset = Math.max(0, offset);
        validateDateOptional(fromDate, "开始日期");
        validateDateOptional(toDate, "结束日期");
        if (fromDate != null && !fromDate.isBlank() && toDate != null && !toDate.isBlank()
                && fromDate.compareTo(toDate) > 0) {
            throw new IllegalArgumentException("开始日期不能晚于结束日期");
        }
        return repository.search(
                ownerId,
                new ChatMaterialRepository.Filter(
                        normalizeUpperOptional(category),
                        normalizeUpperOptional(subType),
                        normalizeUpperOptional(channel),
                        normalizeUpperOptional(sessionKind),
                        blankToNull(sessionId),
                        blankToNull(fromDate),
                        blankToNull(toDate),
                        query
                ),
                safeLimit,
                safeOffset
        );
    }

    public ChatMaterialRepository.SummaryResult summary(String ownerId) {
        return repository.summarize(ownerId);
    }

    public ChatMaterial get(String ownerId, String fileId) {
        requireFileId(fileId);
        return repository.findByFileId(ownerId, fileId)
                .orElseThrow(() -> new IllegalArgumentException("档案素材不存在"));
    }

    public Resource openContent(String ownerId, String fileId) {
        ChatMaterial material = get(ownerId, fileId);
        return new InputStreamResource(fileAssetService.open(
                ownerId,
                material.fileId(),
                FileAssetService.DOMAIN_CHAT_MATERIAL,
                material.turnId(),
                FileAssetService.ROLE_CHAT_ATTACHMENT
        ));
    }

    @Transactional
    public void delete(String ownerId, String fileId) {
        ChatMaterial material = get(ownerId, fileId);
        repository.deleteByFileId(ownerId, material.fileId());
        fileAssetService.unbind(
                ownerId,
                material.fileId(),
                FileAssetService.DOMAIN_CHAT_MATERIAL,
                material.turnId(),
                FileAssetService.ROLE_CHAT_ATTACHMENT
        );
    }

    private String subTypeForMediaType(String mediaType) {
        if (mediaType == null) return "bin";
        return switch (mediaType.toLowerCase(Locale.ROOT)) {
            case "image/png" -> "png";
            case "image/jpeg" -> "jpeg";
            case "image/webp" -> "webp";
            case "image/gif" -> "gif";
            default -> "bin";
        };
    }

    private String extensionForSubType(String subType) {
        return "jpeg".equals(subType) ? "jpg" : subType;
    }

    private String normalizeEnum(String value, String fallback) {
        String candidate = value == null || value.isBlank() ? fallback : value.trim().toUpperCase(Locale.ROOT);
        if (!candidate.matches("[A-Z0-9_]{1,32}")) {
            throw new IllegalArgumentException("分类标识格式非法");
        }
        return candidate;
    }

    private String normalizeUpperOptional(String value) {
        if (value == null || value.isBlank()) return null;
        return value.trim().toUpperCase(Locale.ROOT);
    }

    private String normalizeTitle(String title) {
        if (title == null || title.isBlank()) return "新对话";
        String trimmed = title.trim();
        return trimmed.length() > 120 ? trimmed.substring(0, 120) : trimmed;
    }

    private String blankToNull(String value) {
        return value == null || value.isBlank() ? null : value.trim();
    }

    private void validateDateOptional(String date, String label) {
        if (date == null || date.isBlank()) return;
        try {
            LocalDate.parse(date.trim());
        } catch (RuntimeException exception) {
            throw new IllegalArgumentException(label + "格式非法，应为 YYYY-MM-DD");
        }
    }

    private String requireIdentifier(String value, String label) {
        if (value == null || !value.matches("[a-zA-Z0-9-]{1,128}")) {
            throw new IllegalArgumentException(label + "格式非法");
        }
        return value;
    }

    private void requireFileId(String fileId) {
        if (fileId == null || !fileId.matches("[a-f0-9]{32}")) {
            throw new IllegalArgumentException("素材文件 ID 格式非法");
        }
    }
}

package butvan.agent.network.material.dto;

